  // Importazione massiva lista badge / CSV nel Pannello Admin
  const [bulkText, setBulkText] = useState('');
  const [bulkPreview, setBulkPreview] = useState([]);
  const [bulkImporting, setBulkImporting] = useState(false);
  const [bulkResult, setBulkResult] = useState(null);
  const [totaleBadgeAutorizzati, setTotaleBadgeAutorizzati] = useState(null);

  const estraiBadgeDaTesto = (rawText) => {
    if (!rawText) return [];
    const righe = rawText
      .split(/\r?\n/)
      .map((r) => r.trim())
      .filter(Boolean);

    const badgeSet = new Set();
    const lista = [];

    for (const riga of righe) {
      const parti = riga.split(/[;,|\t\s]+/).map((p) => p.trim()).filter(Boolean);
      for (const parte of parti) {
        const pulito = parte.replace(/^["']|["']$/g, '').toUpperCase();
        if (!pulito) continue;
        if (['BADGE', 'MATRICOLA', 'CODICE', 'ID', 'USER', 'UTENTE'].includes(pulito)) continue;
        if (!badgeSet.has(pulito)) {
          badgeSet.add(pulito);
          lista.push(pulito);
        }
      }
    }
    return lista;
  };

  const aggiornaAnteprimaBulk = (testo) => {
    setBulkText(testo);
    setBulkResult(null);
    setBulkPreview(estraiBadgeDaTesto(testo));
  };

  const gestisciFileBulk = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const contenuto = await file.text();
      aggiornaAnteprimaBulk(contenuto);
    } catch {
      setBulkResult({
        type: 'error',
        message: 'Impossibile leggere il file selezionato.',
      });
    } finally {
      e.target.value = '';
    }
  };

  async function fetchConteggioBadgeAutorizzati() {
    try {
      const { count, error } = await supabase
        .from('utenti_autorizzati')
        .select('*', { count: 'exact', head: true });
      if (!error && typeof count === 'number') {
        setTotaleBadgeAutorizzati(count);
      }
    } catch {
      // Silenzioso se la tabella non è ancora configurata
    }
  }

  const importaBadgeMassivi = async () => {
    if (bulkPreview.length === 0 || bulkImporting) return;
    setBulkImporting(true);
    setBulkResult(null);

    try {
      const { data: esistenti, error: fetchError } = await supabase
        .from('utenti_autorizzati')
        .select('badge')
        .in('badge', bulkPreview);

      if (fetchError) throw fetchError;

      const giaPresenti = new Set(
        (esistenti || []).map((row) => String(row.badge || '').toUpperCase())
      );

      const nuoviBadge = bulkPreview.filter((b) => !giaPresenti.has(b));

      if (nuoviBadge.length === 0) {
        setBulkResult({
          type: 'info',
          message: `Tutti i ${bulkPreview.length} badge inseriti sono già presenti su Supabase. Nessun nuovo record aggiunto.`,
        });
        setBulkImporting(false);
        return;
      }

      const payload = nuoviBadge.map((badge) => ({
        badge,
        attivo: true,
      }));

      const { error: insertError } = await supabase
        .from('utenti_autorizzati')
        .insert(payload);

      if (insertError) throw insertError;

      setBulkResult({
        type: 'success',
        message: `Attivati ${nuoviBadge.length} nuovi badge su Supabase (${giaPresenti.size} già presenti ignorati).`,
      });
      setBulkText('');
      setBulkPreview([]);
      await fetchConteggioBadgeAutorizzati();
    } catch (err) {
      setBulkResult({
        type: 'error',
        message: err?.message || 'Errore durante l’importazione massiva.',
      });
    } finally {
      setBulkImporting(false);
    }
  };

