      setBulkBadgeText((prev) => (prev.trim() ? `${prev.trim()}\n${text.trim()}` : text.trim()));
      setAvviso(`File "${file.name}" letto: controlla l'anteprima qui sotto e clicca Importa.`);
      setTimeout(() => setAvviso(''), 3500);
