    setRepartoInModificaKpi(repNome);
    setKpiEditForm({
      giorniSenzaInfortuni: Number(att.giorniSenzaInfortuni) || 0,
      livelloQualita: Number(att.livelloQualita) || 98.0,
      infortuniAnno: Number(att.infortuniAnno) || 0,
    });
