                          background: '#ecfdf5',
                          border: '1px solid #a7f3d0',
                          color: '#047857',
                          borderRadius: '8px',
                          padding: '3px 8px',
                          fontSize: '0.7rem',
                          fontWeight: 800,
                          cursor: 'pointer',
